const J=JSON.stringify;
const py=value=>value===null?'None':value===true?'True':value===false?'False':Array.isArray(value)?`[${value.map(py).join(', ')}]`:typeof value==='object'?`{${Object.entries(value).map(([k,v])=>`${J(k)}: ${py(v)}`).join(', ')}}`:J(value);
const printed=value=>typeof value==='string'?`'${value.replace(/\\/g,'\\\\').replace(/'/g,"\\'").replace(/\n/g,'\\n')}'`:Array.isArray(value)?`[${value.map(printed).join(', ')}]`:value&&typeof value==='object'?`{${Object.entries(value).map(([k,v])=>`${printed(k)}: ${printed(v)}`).join(', ')}}`:py(value);
const ref=(title,description,code,setup,interpretation,url,language='cypher')=>({title,description:[description],code,language,setup,interpretation:[interpretation],source:source('Official documentation',url),checkedOn:'2026-10-16'});
const withRef=(part,reference)=>({...part,references:[reference]});
const network=(title,explanation,nodes,links,caption)=>view(title,explanation,[],{kind:'network',directed:true,nodes:nodes.map(([label,value])=>({label,value})),edges:links.map(([a,b])=>[a,b]),edgeLabels:links.map(([, ,type])=>type),caption});
const entity=(id,kind='Asset',extra={})=>({id,kind,...extra});
const edge=(id,source,target,type='DEPENDS_ON',extra={})=>({id,source,target,type,...extra});
const G=(nodes,edges)=>({nodes,edges});
const typed=(g,type)=>configured('gdType',{type},op('gdEdges',g));
const identifiers=(rows,field='id')=>configured('gdIds',{field},rows);
const select=(rows,field,operator,value)=>configured('sqlFilter',{field,operator},rows,value);
const literal=value=>configured('sqlText',{value});
const project=(rows,columns)=>configured('sqlProject',{columns},rows);
const sorted=(rows,order)=>configured('sqlSort',{order},rows);
const assets=g=>select(op('gdNodes',g),'kind','=',literal('Asset'));
const seeds=g=>op('gdSeeds',identifiers(assets(g)));
const expand=(rows,edges,mode='required')=>configured('gdExpand',{mode},rows,edges);
const grouped=rows=>sorted(configured('sqlGroup',{key:'origin',field:'current',operation:'count values',output:'n'},op('sqlDistinct',project(rows,'origin,current'))),'origin ASC');
