const countsBody="    by_id={n['id']:n for n in graph['nodes']}\n    completed={}\n    for e in graph['edges']:\n        if e['type']=='HAS_INSPECTION' and by_id[e['source']]['kind']=='Asset' and by_id[e['target']].get('kind')=='Inspection' and by_id[e['target']].get('status')=='closed':\n            completed.setdefault(e['source'],set()).add(e['target'])\n    return [{'origin':key,'n':len(value)} for key,value in sorted(completed.items())]";
const aggregation=lesson({id:'graph-filtering-aggregation',title:'How Many Inspections Were Actually Completed?',topic:queryTopic,openingTitle:'A Repeated Link Has Doubled the Report',opening:['P7 has one completed inspection. An import has accidentally recorded two relationships to that same inspection. Botie’s first count says two. The query counted matching relationships, while the maintenance team asked for distinct completed inspections.','Before adding numbers, we need to decide what a matched row represents. We can inspect status on the bound inspection, then remove repeated asset/inspection pairs before counting them.'],blurb:'Filter bound properties and aggregate at the intended grain, distinguishing paths, relationships and distinct inspection identities.',prerequisites:[before('Connected pattern matching','graph-pattern-matching'),before('Grouping rows','sql-group-by')],history:history('Graph Matches Still Produce Rows That Need a Grain', [source('Cypher aggregation functions','https://neo4j.com/docs/cypher-manual/current/functions/aggregating/'),source('Cypher WITH','https://neo4j.com/docs/cypher-manual/current/clauses/with/'), source("Francis and colleagues, Cypher language paper, 2018", "https://homepages.inf.ed.ac.uk/pguaglia/papers/sigmod18.pdf")], "Property-graph queries made relationships part of the pattern a person could ask the database to match. The Cypher authors’ 2018 language paper described this declarative approach in terms of rows of variable bindings. A matched relationship can create another row even when its endpoint is an entity already seen through a different relationship.", "Reporting over those bindings therefore needed an explicit choice about what to count and which identities to carry forward. Cypher’s aggregate functions and WITH stages provide that control. Our duplicate inspection link keeps the distinction visible: two relationship matches can refer to one inspection. Counting each inspection once requires a stated identity-based duplicate policy, rather than assuming every matched row is a different event."),intuition:[network('Two relationship records point to one inspection','The duplicate edge IDs are separate records, but the target inspection identity is the same.',[['P7','Asset'],['I1','closed'],['I2','open']],[[0,1,'HAS_INSPECTION h1'],[0,1,'HAS_INSPECTION h2'],[0,2,'HAS_INSPECTION h3']],'The completed-inspection count is one. Counting relationship matches would answer a different question.')],parts:[p('Filter the property of the bound inspection','The status belongs to the inspection node. Require the endpoint to have kind Inspection as well as status closed. A mistyped HAS_INSPECTION edge to a technician is a data-quality failure, not completed inspection work.\n\nInspect the node reached by each binding, then require status closed. An absent status does not pass that equality condition. Decide separately whether missing statuses should trigger a data-quality report.',null,'Relationship meaning and node state are different facts.'),p('Write down what one matched row represents','After expansion there is a row for each matched asset/relationship/inspection combination. Two edges to I1 therefore produce two rows. If the desired count is distinct inspections, reduce each row to the asset ID and inspection ID before deduplication.\n\nDeduplicating only the inspection ID globally would lose which asset the count belongs to. Some domains legitimately associate the same inspection with several assets.',null,'The distinct pair preserves the grouping identity and the counted entity.',[example('Collapse repeated asset/inspection pairs','This small program demonstrates the grain change before aggregation.',"pairs=[('P7','I1'),('P7','I1'),('P8','I2')]\nprint(sorted(set(pairs)))","[('P7', 'I1'), ('P8', 'I2')]",'The two P7 matches become one pair while P8 keeps its own association.')]),withRef(p('Keep the grouping variable beside the aggregate','In Cypher, non-aggregate returned expressions define grouping keys. Returning a.id with count(DISTINCT i) gives one count per asset. WITH can name that count for a later condition.\n\nIf a later relationship match multiplies the rows, an already computed count can also be repeated. Inspect intermediate cardinality before summing a summary again.',null,'The group boundary deserves the same attention in Cypher as in SQL.'),ref('Count inspection entities rather than matched links','Only assets with at least one completed match appear in this required-pattern query.',"MATCH (a:Asset)-[:HAS_INSPECTION]->(i:Inspection)\nWHERE i.status=$status\nWITH a, count(DISTINCT i) AS completed\nRETURN a.id AS asset, completed\nORDER BY asset",[inspectionSetup,'Bind status to closed.'],'P7 has one completed inspection. P8 is absent because its inspection is open.','https://neo4j.com/docs/cypher-manual/current/functions/aggregating/')),p('Do not manufacture zero rows after a required match','If no completed inspection matches an asset, that asset has no binding row in this query. Grouping cannot produce a group for an entity that vanished earlier.\n\nIf the report must show zero, preserve the asset population before matching optional inspections. That will be the next lesson’s problem. Replacing a missing number at the end cannot recreate a missing asset row.',null,'Absent groups and groups with zero counts are different query results.'),p('Filter before aggregation only when the question calls for it','Closed status qualifies individual inspections, so it belongs before the count. A requirement such as at least two completed inspections belongs after that grouped count has been calculated.\n\nCounting all inspections and then asking whether any status is closed mixes two different questions. Keep row-level conditions and group-level conditions on the stages where their inputs exist.',null,'Read the count as a statement about a specific population of distinct inspection identities.')],checkpoint:[q('P7 has two HAS_INSPECTION edges to the same closed inspection I1.','How many distinct completed inspections does P7 have?',['1','2','0'],0,'The counted entity is I1, regardless of repeated matching edges.'),tf('The query requires a completed inspection match before grouping. P8 has none.','P8 will automatically appear with a zero count.',false,'A required match removes its row before aggregation.')],quiz:[q('The task asks for assets with at least two distinct completed inspections.','Where does the minimum-count condition belong?',['After computing the per-asset distinct count','On the inspection’s ID spelling','Before any inspection is matched'],0,'The condition describes the group result.'),tf('Two assets can share an inspection in a domain that permits that association.','Deduplicating only inspection IDs globally can lose per-asset counts.',true,'The asset/inspection pair preserves each group’s relationship to the entity.')],practice:[({ ...exercise('Count distinct completed inspections per asset',[
  "Repeated links must not count the same completed inspection twice. Report only assets that have at least one qualifying completed inspection.",
  "Implement completed_counts(graph). Return sorted records {origin: asset_id, n: count} for Asset nodes with at least one distinct closed inspection. Duplicate links to the same inspection count once."
],'completed_counts','graph',countsBody,`print(completed_counts(${py(inspectionGraph)}))`,[{origin:'P7',n:1}],[
  "Start with Asset nodes, then follow HAS_INSPECTION links to nodes whose kind is Inspection and status is closed.",
  "Keep a set of matching inspection IDs per asset. Return origin/n records sorted by origin, excluding zero counts."
],[check('Closed versus open',`completed_counts(${py(inspectionGraph)})`,[{origin:'P7',n:1}]),check('Duplicate relationship',`completed_counts(${py(G(inspectionGraph.nodes,[...inspectionGraph.edges,edge('copy','P7','I1','HAS_INSPECTION')]))})`,[{origin:'P7',n:1}]),check('No completed work',`completed_counts(${py(G(inspectionGraph.nodes.map(n=>n.kind==='Inspection'?{...n,status:'open'}:n),inspectionGraph.edges))})`,[]),check('A second closed inspection counts separately',`completed_counts(${py(G(inspectionGraph.nodes.map(n=>n.id==='I2'?{...n,status:'closed'}:n),[...inspectionGraph.edges,edge('extra','P7','I2','HAS_INSPECTION')]))})`,[{origin:'P7',n:2},{origin:'P8',n:1}])]), question: "How many distinct closed inspections does each inspected asset have?" })],build:build('Count completed inspection identities','An import can repeat a relationship without creating another inspection.','Seed every Asset, expand HAS_INSPECTION, read its kind and status and keep closed Inspection matches. Deduplicate origin/current pairs, count current per origin and order by origin.',{graph:'Maintenance graph'},[sample('One closed inspection and one open inspection',{graph:inspectionGraph},[{origin:'P7',n:1}]),sample('An edge is repeated under a new relationship ID',{graph:G(inspectionGraph.nodes,[...inspectionGraph.edges,edge('copy','P7','I1','HAS_INSPECTION')])},[{origin:'P7',n:1}]),sample('No inspection has finished',{graph:G(inspectionGraph.nodes.map(n=>n.kind==='Inspection'?{...n,status:'open'}:n),inspectionGraph.edges)},[])],grouped(completeBindings),['Filter the bound node’s status.','Project origin and current before distinct, then group by origin.']),});

