const optionalEdges=op('gdTargets',typed(s('graph'),'HAS_INSPECTION'),identifiers(select(select(configured('gdAttach',{fields:'status,kind'},inspectionTargets,s('graph')),'n_kind','=',literal('Inspection')),'n_status','=',literal('closed')),'current'));
const optionalBody="    by_id={n['id']:n for n in graph['nodes']}\n    completed={n['id']:set() for n in graph['nodes'] if n['kind']=='Asset'}\n    for e in graph['edges']:\n        if e['type']=='HAS_INSPECTION' and e['source'] in completed and by_id[e['target']].get('kind')=='Inspection' and by_id[e['target']].get('status')=='closed':\n            completed[e['source']].add(e['target'])\n    return [{'origin':key,'n':len(value)} for key,value in sorted(completed.items())]";
const optional=lesson({id:'graph-optional-patterns',title:'Keep the Pumps That Have No Completed Inspection',topic:queryTopic,openingTitle:'The Asset Most in Need of Attention Has Disappeared',opening:['Botie’s report correctly counts completed inspections, but P8 is missing. P8 only has an open inspection. The maintenance team needs to see that zero, because it is precisely the pump that may need attention.','A required pattern keeps only successful matches. We need to retain each asset even when its qualifying inspection pattern has no match.'],blurb:'Use optional graph patterns without losing the starting population or mistaking an unmatched placeholder for a real inspection.',prerequisites:[before('Graph filtering and counts','graph-filtering-aggregation'),before('Left joins','sql-left-joins')],history:history('Absence Became a Result Worth Preserving', [source('Cypher OPTIONAL MATCH','https://neo4j.com/docs/cypher-manual/current/clauses/optional-match/'), source("Francis and colleagues, Cypher language paper, 2018", "https://homepages.inf.ed.ac.uk/pguaglia/papers/sigmod18.pdf")], "A graph pattern is useful for finding connected records, but an ordinary match can erase a starting entity that has no matching relationship. A maintenance report then loses exactly the pump whose missing inspection it was supposed to expose. Cypher’s 2018 language paper described optional pattern matching as part of the language’s row-binding semantics, carrying the outer-join idea into property-graph queries.", "OPTIONAL MATCH keeps an existing input row and supplies null bindings where the requested pattern has no match. Starting from the asset register therefore lets an uninspected asset remain visible. The missing inspection and the missing asset are different statements. Our report preserves that difference before it counts completed work."),intuition:[network('An open inspection does not satisfy the closed-work pattern','Both assets remain in the report, but only one has a qualifying target.',[['P7','Asset: count 1'],['I1','closed'],['P8','Asset: count 0'],['I2','open']],[[0,1,'HAS_INSPECTION'],[2,3,'HAS_INSPECTION']],'Preserving P8 does not relabel I2 as closed. Its qualifying optional match is absent.')],parts:[p('Begin with the complete asset population','MATCH (a:Asset) establishes every asset that belongs in the report. The next match is allowed to be absent, but the original a remains bound.\n\nIn Python, initialise an empty inspection set for every asset before examining edges. That small ordering decision is what keeps a pump with no relationships at all.',null,'The output population must exist before optional evidence is attached.',[example('Start a count entry for an isolated asset','No inspection edge is required to establish a report row.',"nodes=[{'id':'P7','kind':'Asset'},{'id':'P9','kind':'Asset'}]\nprint({n['id']:set() for n in nodes})","{'P7': set(), 'P9': set()}",'Each empty set can later produce a count of zero.')]),p('Make the qualifying condition part of the optional pattern','The closed-status condition describes which inspection is an acceptable match. In Cypher, a WHERE associated with OPTIONAL MATCH participates in that pattern’s matching conditions.\n\nMoving the condition to a later WITH/WHERE stage can instead remove a row whose optional inspection is NULL. The resulting query may again omit the asset we meant to preserve.',null,'The position of the predicate expresses whether it qualifies a match or filters an already preserved result.'),withRef(p('Count matched identities rather than preserved rows','count(i) ignores NULL bindings, while count(*) counts rows. An asset with no qualifying inspection has an optional placeholder row, so count(*) can produce one even though no inspection exists.\n\nUse count(DISTINCT i) when repeated relationships should not multiply the same inspection. The grouping asset remains in the output with zero.',null,'The placeholder preserves the asset. It is not an inspection.'),ref('Keep zero-completion assets','The status predicate belongs to the optional pattern.',"MATCH (a:Asset)\nOPTIONAL MATCH (a)-[:HAS_INSPECTION]->(i:Inspection)\nWHERE i.status=$status\nRETURN a.id AS asset, count(DISTINCT i) AS completed\nORDER BY asset",[inspectionSetup,'Bind status to closed.'],'P7 appears with 1 and P8 with 0.','https://neo4j.com/docs/cypher-manual/current/clauses/optional-match/')),p('Distinguish no inspection from an inspection with unknown properties','An actual inspection node may lack its completion date or status. That is different from having no inspection relationship. Inspect the node identity when diagnosing missing values.\n\nA report can preserve both facts by returning inspection IDs and their properties separately. Do not use a nullable descriptive field as proof that no node matched.',null,'NULL in one property is not evidence that the whole related entity is absent.'),p('Keep independent optional branches from multiplying each other','Suppose an asset has two inspections and three manuals. Matching both branches can produce six combinations. Counting inspections after that multiplication requires an explicit distinct policy or separate aggregation of each branch.\n\nOPTIONAL MATCH preserves absence; it does not eliminate fan-out. Work through one small asset with multiple matches on both sides before trusting a dashboard total.',null,'The workshop has one optional branch so we can observe its preserved row directly.'),p('Build the qualifying edge set before optional expansion','Our components first identify closed inspection targets and retain only relationships pointing to those targets. Optional expansion then preserves a binding whose source has no qualifying relationship.\n\nThe resulting NULL current value is excluded by count values. The distinct origin/current pair prevents repeated links from adding another inspection.',null,'This record mechanism mirrors the question’s matching boundary without pretending to parse OPTIONAL MATCH syntax.')],checkpoint:[q('P8 has an open inspection but no closed inspection. The report starts from every Asset and optionally matches closed inspections.','What should P8’s completed count be?',['0','1','The row must disappear'],0,'The asset survives while the qualifying inspection binding is absent.'),tf('An optional row has i=NULL.','count(*) and count(i) necessarily produce the same result.',false,'count(*) includes the preserved row, while count(i) excludes its NULL inspection binding.')],quiz:[q('An inspection node exists with a missing note property.','What establishes that an inspection actually matched?',['The non-NULL inspection identity','Whether its note contains text','Whether count(*) is large'],0,'A nullable property is not a reliable match sentinel.'),tf('Two independent optional branches can each have multiple matches.','Their combination can multiply intermediate rows.',true,'Optionality preserves missing matches but does not remove combinations of present matches.')],practice:[({ ...exercise('Include every asset in the completed-inspection report',[
  "An asset without a completed inspection is still important to the maintenance report. Extend the earlier count to keep every Asset, including zero matches.",
  "Implement all_completed_counts(graph). Return origin and n for every Asset in ID order. Count distinct closed inspection targets; preserve assets with no qualifying match as n=0."
],'all_completed_counts','graph',optionalBody,`print(all_completed_counts(${py(inspectionGraph)}))`,[{origin:'P7',n:1},{origin:'P8',n:0}],[
  "Initialise an empty inspection set for every Asset before considering edges.",
  "Follow HAS_INSPECTION to closed Inspection nodes, adding each target once. Emit origin/n records in asset-ID order, including the empty sets as zero."
],[check('Open-only asset survives',`all_completed_counts(${py(inspectionGraph)})`,[{origin:'P7',n:1},{origin:'P8',n:0}]),check('Isolated asset survives',`all_completed_counts(${py(G([...inspectionGraph.nodes,entity('P9')],inspectionGraph.edges))})`,[{origin:'P7',n:1},{origin:'P8',n:0},{origin:'P9',n:0}]),check('No edges',`all_completed_counts(${py(G(inspectionGraph.nodes,[]))})`,[{origin:'P7',n:0},{origin:'P8',n:0}]),check('Duplicate target counted once',`all_completed_counts(${py(G(inspectionGraph.nodes,[...inspectionGraph.edges,edge('copy','P7','I1','HAS_INSPECTION')]))})`,[{origin:'P7',n:1},{origin:'P8',n:0}])]), question: "Can the report keep assets with no completed inspection?" })],build:build('Preserve assets with no qualifying inspection','The pump with only open work must remain visible as zero.','Seed all Asset IDs. Keep HAS_INSPECTION edges whose targets are closed. Expand optionally, deduplicate origin/current pairs and count non-NULL current per origin.',{graph:'Maintenance graph'},[sample('P8 has only open work',{graph:inspectionGraph},[{origin:'P7',n:1},{origin:'P8',n:0}]),sample('An isolated P9 enters the registry',{graph:G([...inspectionGraph.nodes,entity('P9')],inspectionGraph.edges)},[{origin:'P7',n:1},{origin:'P8',n:0},{origin:'P9',n:0}]),sample('The graph has assets but no inspections',{graph:G([entity('P2'),entity('P1')],[])},[{origin:'P1',n:0},{origin:'P2',n:0}])],grouped(expand(seeds(s('graph')),optionalEdges,'optional')),['Qualify inspection targets before optional expansion.','Count values rather than rows so the NULL placeholder contributes zero.']),});

const cycleGraph=G(['P7','S1','S2','S3'].map(id=>entity(id)),[edge('a','P7','S1'),edge('b','S1','S2'),edge('c','S2','P7'),edge('d','S2','S3')]);
const reachBody="    from collections import deque\n    neighbours={}\n    for e in graph['edges']:\n        if e['type']=='DEPENDS_ON': neighbours.setdefault(e['source'],[]).append(e['target'])\n    visited={start}\n    queue=deque([(start,0)])\n    while queue:\n        current,depth=queue.popleft()\n        if depth>=max_depth: continue\n        for target in neighbours.get(current,[]):\n            if target not in visited:\n                visited.add(target)\n                queue.append((target,depth+1))\n    return sorted(visited-{start})";
const traversal=lesson({id:'graph-traversal-cycles',title:'Follow a Dependency Without Following It Forever',topic:pathTopic,openingTitle:'The Dependency List Points Back to the Pump',opening:['P7 requires S1, S1 requires S2, and a later import says S2 requires P7. Botie’s recursive search keeps returning to the same equipment. Even if the cycle describes a real feedback dependency, our list of affected entities should not repeat forever.','We need to decide what the traversal is collecting and when a node has already been dealt with. For distinct reachable assets, a breadth-first search can remember visited IDs and stop expansion at a stated depth.'],blurb:'Separate reachability from path enumeration, handle cycles explicitly and interpret bounded traversal results without promising complete discovery.',prerequisites:[before('Connected patterns','graph-pattern-matching'),before('Recursive queries','sql-recursive-ctes')],history:history('Unknown-Length Connections Needed Repeated Expansion',[source('Cypher authors on variable-length traversal needs','https://homepages.inf.ed.ac.uk/pguaglia/papers/sigmod18.pdf'),source('Cypher variable-length paths','https://neo4j.com/docs/cypher-manual/current/patterns/variable-length-paths/')],'The early Neo4j use case described by the Cypher authors included access through variable-length relationships. A fixed sequence of joins or pattern segments cannot express every unknown chain length conveniently. Graph query languages therefore provide bounded or variable-length path matching.','The repeated step does not decide the answer’s grain. A list of reachable nodes, every distinct path and the shortest path are different questions. Our teaching traversal collects nodes once, which gives the visited set a clear purpose.'),intuition:[network('A cycle returns to an already discovered node','P7, S1 and S2 form a directed cycle. S3 lies one step beyond S2.',[['P7','depth 0'],['S1','depth 1'],['S2','depth 2'],['S3','depth 3']],[[0,1,'DEPENDS_ON'],[1,2,'DEPENDS_ON'],[2,0,'DEPENDS_ON'],[2,3,'DEPENDS_ON']],'With maximum depth 2, the report includes S1 and S2, excludes the starting P7, and makes no completeness claim about deeper dependencies.')],parts:[p('Choose whether the answer contains nodes or routes','Reachability asks whether a node can be reached at all. Path enumeration retains the route, so two different paths to S2 can both be useful results. A global visited set is suitable for our distinct reachability answer, but would suppress alternative routes if we were trying to enumerate them.\n\nState this before writing a recursion. The same graph can legitimately produce different answers under different output contracts.',null,'The challenge returns distinct reachable IDs, excluding the starting ID.'),p('Keep a queue of nodes still to explore','Breadth-first search begins with the starting node at depth zero. Remove the oldest queued entry, inspect its outgoing dependency edges and add unseen targets at the next depth. Mark a target visited when it is queued so two frontier nodes do not enqueue it repeatedly.\n\nBecause each step has equal hop cost, the first discovery gives the minimum number of relationships from the start. Weighted cost is a different question.',null,'The queue is work still to do; the visited set records identities already discovered.',[example('Expand the first frontier','This program only inspects the first step. The exercise must keep expanding safely.',`g=${py(cycleGraph)}\nfrontier=['P7']\nnext_ids={e['target'] for e in g['edges'] if e['type']=='DEPENDS_ON' and e['source'] in frontier}\nprint(sorted(next_ids))`,"['S1']",'The next frontier comes from outgoing edges of the current frontier, not every edge in the graph.')]),withRef(p('Bound a real path query deliberately','The Cypher range *1..3 requests paths from one through three relationships. DISTINCT on the returned node removes repeated endpoints from different matching paths. The query below also excludes the starting node if a cycle returns to it.\n\nCypher’s relationship-reuse rules and a global-visited BFS are different mechanisms. For this bounded reachability question their intended endpoint set aligns, but the path rows and search work need not be identical.',null,'A hop bound says how far the query may explore; it does not certify the graph has no deeper nodes.'),ref('Ask for dependencies within three hops','This uses established variable-length relationship syntax; newer quantified syntax is another documented option.',"MATCH (a:Asset {id:$asset})-[:DEPENDS_ON*1..3]->(d:Asset)\nWHERE d <> a\nRETURN DISTINCT d.id AS dependency ORDER BY dependency",["In an empty test database run CREATE (p:Asset {id:'P7'}),(a:Asset {id:'S1'}),(b:Asset {id:'S2'}),(c:Asset {id:'S3'}),(p)-[:DEPENDS_ON]->(a),(a)-[:DEPENDS_ON]->(b),(b)-[:DEPENDS_ON]->(p),(b)-[:DEPENDS_ON]->(c).",'Bind asset to P7.'],'The result includes S1, S2 and S3. The chosen three-hop cap is part of the report’s scope.','https://neo4j.com/docs/cypher-manual/current/patterns/variable-length-paths/')),p('Interpret the depth boundary honestly','At depth two, S2 has been discovered but its outgoing edges are not expanded. S3 is therefore absent from the two-hop result. Calling that result “all dependencies” would overstate what was checked.\n\nA depth cap also does not bound the number of nodes tightly in a high-degree graph. Add operational time and result-size limits, and report truncation or failure rather than presenting partial results as a complete answer.',null,'The workshop caps the reachable set to protect responsiveness and reports a limit error rather than silently trimming it.'),p('Filter allowed relationships before expanding them','An edge type restriction prevents unrelated meanings from entering the traversal. A tenant or access restriction serves a different purpose: it determines which data the caller may use at all. Apply those restrictions before or during expansion, including intermediate nodes.\n\nA shallow traversal can still read forbidden data. Treat depth and output limits as resource controls, never as permission checks.',null,'The fixture is fully permitted. Later retrieval applies a scoped graph before either dependency or document expansion.'),p('Inspect cycles as domain evidence as well as an algorithm concern','A cycle in a supply dependency may be an impossible import or a real mutually dependent system. A visited set makes our computation terminate, but it does not decide whether the cycle is valid in the domain.\n\nKeep enough edge identity and provenance to investigate it. If the application requires a directed acyclic hierarchy, enforce or audit that separate invariant rather than assuming the traversal repaired the data.',null,'Algorithmic termination and domain correctness solve different problems.')],checkpoint:[q('P7→S1→S2→S3, with a return edge S2→P7. The maximum depth is 2 and the start is excluded.','Which IDs belong in the result?',['S1 and S2','S1, S2 and S3','P7 only'],0,'S3 is at depth 3, beyond this report’s scope.'),tf('The task asks to enumerate every distinct path to a node.','A global visited set that keeps only first discovery necessarily preserves every path.',false,'It suppresses alternative routes that reach an already visited node.')],quiz:[q('An edge leads through another tenant’s private node but the path is only one hop long.','Does the short depth make it permissible?',['No, access rules must still apply','Yes, only long paths need authorisation','Yes, if the final label is hidden'],0,'A work bound is not an access-control boundary.'),tf('A BFS visited set prevents repeated expansion of a cycle.','That alone does not establish that the cycle is valid equipment data.',true,'The domain may impose a separate acyclic-dependency rule.')],practice:[({ ...exercise('Find distinct dependencies within the hop budget',[
  "A dependency can lead to another dependency and eventually back to the start. Implement reachable(graph, start, max_depth) without looping on that cycle.",
  "Follow outgoing DEPENDS_ON edges for at most max_depth links, where max_depth is a nonnegative integer. Return sorted distinct reached IDs, excluding start even if a cycle returns to it. Zero depth gives no dependencies."
],'reachable','graph, start, max_depth',reachBody,`print(reachable(${py(cycleGraph)}, 'P7', 2))`,['S1','S2'],[
  "Keep the number of links used beside each node waiting to be explored. A queue processes nearest discoveries first.",
  "Mark IDs visited when they enter the queue, so cycles and duplicate routes cannot keep adding the same node.",
  "Do not expand a node at the depth limit. Return the visited IDs other than start in sorted order."
],[check('Cycle and two-hop boundary',`reachable(${py(cycleGraph)}, 'P7', 2)`,['S1','S2']),check('The next depth exposes S3',`reachable(${py(cycleGraph)}, 'P7', 3)`,['S1','S2','S3']),check('Zero budget',`reachable(${py(cycleGraph)}, 'P7', 0)`,[]),check('Sink has no outgoing dependencies',`reachable(${py(cycleGraph)}, 'S3', 5)`,[])]), question: "Which dependencies can be reached within the allowed number of links?" })],build:build('Traverse the dependency cycle within a stated depth','Botie must stop revisiting equipment and keep the report’s reach explicit.','Choose DEPENDS_ON edges, compute bounded reachable nodes, exclude depth zero and collect sorted IDs.',{graph:'Directed dependency graph',start:'Starting asset',depth:'Maximum hop depth'},[sample('The report stops at two hops',{graph:cycleGraph,start:'P7',depth:2},['S1','S2']),sample('One extra hop exposes S3',{graph:cycleGraph,start:'P7',depth:3},['S1','S2','S3']),sample('No expansion is requested',{graph:cycleGraph,start:'P7',depth:0},[])],identifiers(select(op('gdReach',typed(s('graph'),'DEPENDS_ON'),s('start'),s('depth')),'depth','>',c(0))),['A visited set belongs inside reachability expansion.','Filter out the zero-depth start after traversal.'], "The component computes a bounded set of reached nodes and their first-discovery depths. It does not expose every route or its internal queue, and it does not run a graph database. An omitted node may lie beyond the supplied hop limit."),});

const routeGraph=G(['A','B','C','D'].map(id=>entity(id,'Location')),[edge('ab','A','B','ROUTE',{minutes:9}),edge('ac','A','C','ROUTE',{minutes:2}),edge('cb','C','B','ROUTE',{minutes:2}),edge('bd','B','D','ROUTE',{minutes:1}),edge('cd','C','D','ROUTE',{minutes:20})]);
const shortestBody="    import heapq\n    neighbours={}\n    for e in graph['edges']:\n        if e['type']!='ROUTE': continue\n        cost=e.get('minutes')\n        if isinstance(cost,bool) or not isinstance(cost,(int,float)) or not __import__('math').isfinite(cost) or cost<0: raise ValueError('Costs must be finite and nonnegative')\n        neighbours.setdefault(e['source'],[]).append((e['target'],cost))\n    best={start:0}\n    heap=[(0,start)]\n    while heap:\n        cost,current=heapq.heappop(heap)\n        if cost!=best[current]: continue\n        if current==target: return cost\n        for nxt,weight in neighbours.get(current,[]):\n            candidate=cost+weight\n            if candidate<best.get(nxt,float('inf')):\n                best[nxt]=candidate\n                heapq.heappush(heap,(candidate,nxt))\n    return None";
const shortest=lesson({id:'graph-shortest-paths',title:'The Route with Fewer Stops Takes Longer',topic:pathTopic,openingTitle:'Two Hops Are Slower Than Three',opening:['The maintenance cart can reach B directly from A in nine minutes. Going through C takes four minutes. A search that chooses the fewest relationships selects the direct route, even though the crew asked for the quickest one.','We need to define what “shortest” measures. Hop count treats every edge equally. Travel time assigns a cost to each edge, so the route choice must compare accumulated costs rather than the number of connections.'],blurb:'Distinguish minimum-hop paths from minimum-cost paths and implement Dijkstra’s nonnegative-cost frontier with explicit unreachable and tie semantics.',prerequisites:[before('Breadth-first traversal','graph-traversal-cycles')],history:history('Shortest Routes Needed a Cost-Aware Search',[source('Dijkstra source-target implementation and assumptions','https://neo4j.com/docs/graph-data-science/current/algorithms/dijkstra-source-target/')],'Dijkstra’s shortest-path method is used to find minimum accumulated cost in graphs with suitable nonnegative weights. Neo4j’s Graph Data Science documentation exposes that method separately from simple hop-count path matching. The algorithm keeps the cheapest unsettled distance visible rather than committing to the first route discovered.','For our cart, that distinction allows a route with an extra stop to win. The Python exercise implements a small nonnegative-weight version so we can inspect why the earlier expensive route is replaced.'),intuition:[network('Compare route costs rather than counting arrows','Each edge label is travel time in minutes.',[['A','Cart start'],['B','Workshop'],['C','Side corridor'],['D','Destination']],[[0,1,'9 min'],[0,2,'2 min'],[2,1,'2 min'],[1,3,'1 min'],[2,3,'20 min']],'The cheapest A-to-D route goes through C and B. More relationships can still mean less total time.')],parts:[p('Choose the quantity to minimise','Minimum hops answers how many links must be followed. Minimum travel time answers how much edge cost accumulates. Neither is inherently the correct question; the operational objective decides.\n\nA directed route can be traversable in one direction only. If a corridor is bidirectional, represent both permitted directions or use a graph projection whose orientation is deliberately defined.',null,'Our route graph is directed, and every minutes property uses the same unit.'),p('Replace first discovery with the best known cost','B is first discovered with cost nine through the direct edge. When C is expanded, the route through C offers a lower cost to B. The algorithm updates B’s best value rather than treating its first discovery as final.\n\nA priority queue makes the lowest current candidate the next one to process. Older queued entries for a node can become stale after an improvement, so the code checks them against the best-known distance.',null,'The visited-on-discovery rule from unweighted BFS does not implement this weighted objective.',[example('Compare the two routes to B','This isolates the accumulated-cost comparison before implementing a search.',"direct=9\nvia_c=2+2\nprint({'direct':direct,'via_C':via_c})","{'direct': 9, 'via_C': 4}",'The longer-in-hops route has the smaller time cost.')]),p('Why nonnegative weights matter','Once the cheapest candidate is settled, nonnegative future edges cannot produce a cheaper route by leaving that settled frontier and later subtracting cost. That property supports Dijkstra’s decision rule.\n\nNegative weights require another algorithm and careful treatment of negative cycles. A missing weight is not automatically zero. Validate the graph projection’s weight field and units before running the method.',null,'The exercise accepts zero-cost edges but rejects negative or nonfinite costs.'),withRef(p('Do not mistake Cypher shortestPath for weighted optimisation','A hop-oriented shortestPath pattern does not automatically minimise a minutes property just because the relationship contains it. Weighted algorithms such as GDS Dijkstra use an explicitly projected weight.\n\nFor the tiny setup below, the reference query enumerates bounded paths and orders their summed cost. It exposes the objective in ordinary Cypher, but it is not a scalable replacement for a dedicated weighted algorithm.',null,'This reference is limited to a tiny acyclic graph with all relevant paths within three hops.'),ref('Inspect accumulated route costs on the tiny graph','The small bounded enumeration is for explanation, not a production path planner.',"MATCH p=(a:Location {id:$start})-[:ROUTE*1..3]->(b:Location {id:$target})\nWITH p, reduce(total=0, r IN relationships(p) | total+r.minutes) AS cost\nRETURN [n IN nodes(p) | n.id] AS route, cost\nORDER BY cost, route\nLIMIT 1",["In a fresh test database run CREATE (a:Location {id:'A'}),(b:Location {id:'B'}),(c:Location {id:'C'}),(d:Location {id:'D'}),(a)-[:ROUTE {minutes:9}]->(b),(a)-[:ROUTE {minutes:2}]->(c),(c)-[:ROUTE {minutes:2}]->(b),(b)-[:ROUTE {minutes:1}]->(d),(c)-[:ROUTE {minutes:20}]->(d).",'Bind start A and target D. Use GDS Dijkstra with an appropriate projection for larger weighted problems.'],'The route A,C,B,D has cost 5. The LIMIT does not prevent the preceding enumeration from doing substantial work on a different graph.','https://neo4j.com/docs/graph-data-science/current/algorithms/dijkstra-source-target/')),p('Keep unreachable and zero-cost answers distinct','If the destination cannot be reached, return no distance, represented by None in the exercise. If start equals target, the empty route has cost zero. A reachable route can also legitimately have zero total cost.\n\nDo not replace absence with zero. That would make a disconnected workshop look as though the cart were already there.',null,'The challenge returns the minimum cost only, so equally cheap paths do not require a route-selection tie break.'),p('A computed route is only as current as its allowed edges','A closed corridor or a restricted area must be removed before routing. Applying permission checks only after choosing the cheapest path can select an unusable route and obscure valid alternatives.\n\nTravel times may change while the cart moves. A graph snapshot provides an estimate under stated conditions, not a guarantee about the physical journey. Validate operational safety separately from minimising cost.',null,'The workshop filters ROUTE edges and computes costs from the supplied snapshot.')],checkpoint:[q('A→B costs 9; A→C costs 2; C→B costs 2.','Which route has the lower accumulated cost?',['A→C→B','A→B','They must tie because both reach B'],0,'The two-edge route costs four minutes.'),tf('An edge has a negative minutes value.','The lesson’s Dijkstra implementation should reject that input.',true,'Its settlement rule assumes nonnegative costs.')],quiz:[q('No directed route connects A to D.','What should shortest_cost return under this contract?',['None','0','The largest edge cost'],0,'Unreachability is different from a reachable zero-cost route.'),tf('A query uses LIMIT 1 after enumerating many bounded paths and sorting by cost.','The limit alone proves that little search work was done.',false,'The engine may have to produce and compare many candidates before limiting the output.')],practice:[({ ...exercise('Find the minimum nonnegative travel cost',[
  "The direct route can cost more minutes than a route through another location. Search by accumulated travel cost rather than by the number of links.",
  "Implement shortest_cost(graph,start,target). Use directed ROUTE edges and finite nonnegative minutes. Return the cheapest total, None if unreachable, or 0 when start equals target. Raise ValueError for invalid ROUTE weights."
],'shortest_cost','graph, start, target',shortestBody,`print(shortest_cost(${py(routeGraph)}, 'A', 'D'))`,5,[
  "Validate every ROUTE weight before searching. Use only finite nonnegative numbers, excluding Boolean values as weights.",
  "Track the best known total per node. If a newly found route is cheaper, update that candidate rather than keeping the first route encountered.",
  "heapq can examine the lowest-cost pending route next. Return None when no route reaches the target."
],[check('Cheaper multi-hop route',`shortest_cost(${py(routeGraph)}, 'A','D')`,5),check('Unreachable reverse direction',`shortest_cost(${py(routeGraph)}, 'D','A')`,null),check('Zero-length route',`shortest_cost(${py(routeGraph)}, 'A','A')`,0),['Reject negative route cost',`try:\n    shortest_cost(${py(G(routeGraph.nodes,[edge('bad','A','B','ROUTE',{minutes:-1})]))}, 'A','B')\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError('Negative cost accepted')`],check('Zero-cost relationship',`shortest_cost(${py(G(routeGraph.nodes,[edge('zero','A','B','ROUTE',{minutes:0})]))}, 'A','B')`,0)]), question: "Which directed route has the lowest total travel time?" })],build:build('Choose the route by travel time','The fewest-hop shortcut loses to a longer route with lower accumulated minutes.','Choose ROUTE edges, calculate nonnegative path costs from start, and read the destination cost. Preserve NULL for unreachable destinations.',{graph:'Directed weighted route graph',start:'Start location',target:'Destination'},[sample('Three hops beat the direct corridor',{graph:routeGraph,start:'A',target:'D'},5),sample('The direction is reversed',{graph:routeGraph,start:'D',target:'A'},null),sample('The cart is already at the destination',{graph:routeGraph,start:'A',target:'A'},0)],op('gdCost',configured('gdShortest',{weight:'minutes'},typed(s('graph'),'ROUTE'),s('start')),s('target')),['Use accumulated cost rather than first discovery.','Do not turn an unreachable result into zero.']),});

const badKeys=[{id:'P7',kind:'Asset'},{id:'P7',kind:'Asset'},{kind:'Asset'},{id:'',kind:'Asset'},{id:'P8',kind:'Asset'}];
const constraints=lesson({id:'graph-constraints-indexes',title:'Which Rules Must Every Asset Write Preserve?',topic:writeTopic,openingTitle:'The Second P7 Broke the Meaning of Every Match',opening:['A query that used to locate one P7 now finds two nodes. Some relationships point to one copy and some to the other. Botie cannot repair that ambiguity by choosing whichever match appears first.','The application needs a durable identity rule enforced at the write boundary. An index can help find an asset, but a constraint is what rejects a forbidden duplicate. Those responsibilities are related without being interchangeable.'],blurb:'Separate key presence, uniqueness and lookup performance, then audit existing data before installing graph constraints.',prerequisites:[before('Source-qualified identity','graph-database-identity'),before('SQL constraints','sql-constraints')],history:history('Flexible Records Still Needed Shared Invariants',[source('Neo4j constraint creation and backing indexes','https://neo4j.com/docs/cypher-manual/current/schema/constraints/create-constraints/'),source('Cypher 2018 language and schema facilities','https://homepages.inf.ed.ac.uk/pguaglia/papers/sigmod18.pdf')],'Property graphs let applications evolve node properties without requiring every category to have an identical record shape. As those graphs became application databases, shared write rules remained necessary. The Cypher language paper includes schema-definition capabilities alongside queries and updates; current Neo4j constraints make selected identity and property requirements enforceable.','The purpose here is narrower than making every node identical. All Asset nodes need an unambiguous application identity, while different kinds of equipment can still have different optional properties.'),intuition:[network('Duplicate node identities split the maintenance history','The display shows two different stored nodes with the same forbidden application key.',[['P7 copy A','Asset key P7'],['I1','Inspection'],['P7 copy B','Asset key P7'],['I2','Inspection']],[[0,1,'HAS_INSPECTION'],[2,3,'HAS_INSPECTION']],'A uniqueness constraint prevents new duplicate keys. Existing conflicting nodes need review before the constraint can be created.')],parts:[p('Separate presence from uniqueness','A uniqueness rule prevents repeated known key values. It does not necessarily require every node to carry that key. A node with no application ID can remain difficult to address even when all present IDs are unique.\n\nFor this import audit, a valid ID is a nonempty string. Count missing, blank or nonstring IDs separately from duplicate known IDs. Production databases may offer key, existence and type constraints with edition-specific availability.',null,'Passing the duplicate check does not establish that every record has a usable identity.'),p('Audit the existing records first','Creating a constraint over conflicting data can fail. Inspect the duplicate groups and missing keys, decide which nodes are genuine duplicates, and preserve their attached relationships while repairing them.\n\nDo not delete a duplicate-looking node simply because its ID repeats. Its relationships may contain the only copy of an inspection association. A migration needs a reviewed reconciliation rule and a recovery path.',null,'The exercise reports problems without changing the records.',[example('Count missing key values separately','These rows have no duplicate valid ID, but one lacks any ID.',"nodes=[{'id':'P7'},{'name':'Unregistered pump'}]\nprint(sum(not isinstance(n.get('id'),str) or not n['id'] for n in nodes))",'1','An empty duplicate list would not make this import valid.')]),withRef(p('Install the identity constraint deliberately','The first statement below creates uniqueness for Asset.id. Neo4j backs property uniqueness constraints with an index, so it can also support the identity lookup. This does not turn every other property into a constrained field.\n\nProperty existence and type constraints, and node-key constraints, have edition/version requirements. Validate required fields at ingestion and use the database-supported rule set for the deployment; do not advertise a uniqueness-only rule as mandatory-key enforcement.',null,'A query plan and a data invariant answer different questions.'),ref('Create and inspect an asset identity constraint','Run schema changes with an authorised administrative role in a disposable test database.',"CREATE CONSTRAINT asset_id_unique IF NOT EXISTS\nFOR (a:Asset) REQUIRE a.id IS UNIQUE;\nSHOW CONSTRAINTS;",['Use an empty Neo4j test database or first repair duplicate Asset.id values.','This uniqueness constraint does not require id on every Asset. For deployments that support it, CREATE CONSTRAINT asset_id_required IF NOT EXISTS FOR (a:Asset) REQUIRE a.id IS NOT NULL adds an existence rule; check the edition requirement before running it.'],'The installed constraint rejects duplicate known IDs. Missingness remains a separate obligation.','https://neo4j.com/docs/cypher-manual/current/schema/constraints/create-constraints/')),p('Use indexes for the predicates that actually locate nodes','An index on a label/property combination can help a selective starting lookup. It does not automatically speed every relationship traversal or every expression applied to that property.\n\nInspect the plan for the actual query and representative parameters. Extra indexes consume storage and add write work, so create them around measured access patterns rather than every possible field.',null,'Index presence is not proof that a particular query uses it.'),p('Keep application rules alongside database rules','A uniqueness constraint does not verify that an asset belongs to the caller’s tenant or that a proposed dependency is physically sensible. The database may enforce some structural rules while application policy checks the rest.\n\nDocument which boundary owns each rule and test writes through every supported path. A bulk loader that bypasses an application check can otherwise reintroduce the same problem.',null,'The workshop’s independent duplicate and missing-ID branches are an audit, not an installed database constraint.')],checkpoint:[q('The IDs are P7, P7, missing, empty string and P8. A usable ID is a nonempty string.','What should the audit report?',['Duplicate P7 and two unusable IDs','Only duplicate P7','Five duplicates'],0,'Presence and repetition are separate checks.'),tf('A uniqueness-only property constraint exists.','That necessarily requires every node to have the property.',false,'Required presence needs a separate supported rule.')],quiz:[q('An index exists on Asset.id but a query filters on an unrelated expression.','What should establish whether the index helps?',['The actual query plan and measurements','Its mere presence in the schema','The number of node labels'],0,'Access paths depend on the predicate and planner.'),tf('Duplicate application IDs already exist.','They may need reconciliation before a uniqueness constraint can be created.',true,'Existing conflicting data can prevent constraint creation.')],practice:[({ ...exercise('Report duplicate and unusable node IDs',[
  "An import can reuse a valid ID or fail to supply one at all. Report those as separate problems before linking records.",
  "Implement key_issues(nodes). Return [sorted_duplicate_ids, unusable_count]. A usable ID is a nonempty string. Count each repeated usable ID once; missing, blank and nonstring IDs contribute only to unusable_count. Do not mutate inputs."
],'key_issues','nodes',"    from collections import Counter\n    usable=[n.get('id') for n in nodes if isinstance(n.get('id'),str) and n['id']]\n    counts=Counter(usable)\n    return [sorted(k for k,n in counts.items() if n>1),len(nodes)-len(usable)]",`print(key_issues(${py(badKeys)}))`,[['P7'],2],[
  "Keep a frequency table for usable IDs and a separate invalid-record counter. For this exercise usable means a nonempty string; whitespace-only strings are not additionally rejected.",
  "Return a two-element list: sorted repeated usable IDs, then the invalid count. Each repeated ID appears once in the first list."
],[check('Both categories',`key_issues(${py(badKeys)})`,[['P7'],2]),check('Valid unique keys',`key_issues([{'id':'P1'},{'id':'P2'}])`,[[],0]),check('Nontext identifiers',`key_issues([{'id':7},{'id':None}])`,[[],2]),check('Each repeated key once',`key_issues([{'id':'B'},{'id':'A'},{'id':'B'},{'id':'B'},{'id':'A'}])`,[['A','B'],0])]), question: "Which node IDs repeat, and how many records have no usable ID?" })],build:build('Audit identity before installing the constraint','Some imported nodes repeat an ID and others have no usable one.','Find duplicate nonempty text IDs and count unusable IDs on separate branches. Collect duplicates first and missing count second.',{nodes:'Unvalidated imported node records'},[sample('Duplicate and absent keys occur together',{nodes:badKeys},[['P7'],2]),sample('Uniqueness passes while presence fails',{nodes:[{id:'P1'},{id:7},{id:null}]},[[],2]),sample('Every key is valid and distinct',{nodes:[{id:'P1'},{id:'P2'}]},[[],0])],op('pack',op('gdDuplicates',s('nodes')),op('gdMissingIds',s('nodes'))),['Do not make the missing-ID count depend on whether duplicates exist.']),});

