const requests=[{id:'P7',expected_revision:2,approved:true},{id:'P8',expected_revision:3,approved:true},{id:'P7',expected_revision:2,approved:false}];
const updates=lesson({id:'graph-safe-updates',title:'The Graph Changed While the Approval Was Waiting',topic:writeTopic,openingTitle:'An Approved Plan Is Now Based on an Old Record',opening:['Botie prepared a change for P8 when its revision was three. While a person reviewed that proposal, another technician updated P8 to revision four. Applying the old plan without checking would overwrite a decision made with newer information.','We need to separate preparing a change, approving it and committing it against current state. A snapshot check can reveal an obviously stale request, but only the database transaction can protect the final write from concurrent changes.'],blurb:'Treat approvals and snapshot checks as preparation, then use authorised, parameterised transactions with explicit conflict and retry behaviour.',prerequisites:[before('Graph constraints','graph-constraints-indexes'),before('SQL transactions','sql-transactions')],history:history('Connected Updates Needed a Transaction Boundary', [source('Neo4j Python driver transactions','https://neo4j.com/docs/python-manual/current/transactions/'),source('Cypher MERGE','https://neo4j.com/docs/cypher-manual/current/clauses/merge/'), source("Jim Gray: The Transaction Concept, 1981", "https://www.cs.utexas.edu/~dahlin/Classes/GradOS/papers/Gray81.pdf"), source("Francis and colleagues, Cypher language paper, 2018", "https://homepages.inf.ed.ac.uk/pguaglia/papers/sigmod18.pdf")], "An application update can span several stored facts. Creating an inspection and connecting it to an asset should not leave an unexplained half-result if execution fails between writes. Transaction-processing work, including Gray’s 1981 account, made the commit-or-rollback unit explicit. Property-graph languages brought updates to nodes and relationships into that same application-database problem; the Cypher authors documented the language in 2018.", "Our maintenance approval adds evidence to the transaction’s meaning. A person approved a particular action for a particular observed state, so the database must recheck that state before committing. Neo4j drivers may retry selected transient transaction failures, which means an external effect inside the retried function needs separate handling. A transaction protects its database unit of work, not every action the caller might perform elsewhere."),intuition:[network('Approval belongs to a particular proposed change','The stored asset has advanced beyond one proposal’s expected revision.',[['Proposal P7','approved; expects revision 2'],['P7','current revision 2'],['Proposal P8','approved; expects revision 3'],['P8','current revision 4']],[[0,1,'PROPOSES_CHANGE'],[2,3,'PROPOSES_CHANGE']],'Only P7 passes the snapshot comparison. Passing it still does not commit the change or protect against a later concurrent write.')],parts:[p('Keep the request separate from the stored entity','A proposal should identify its target, intended change, caller and the state it was based on. The approval should be tied to that proposal rather than a general reusable “yes.”\n\nOur exercise deliberately selects eligible target IDs only. It does not apply status changes, validate arbitrary payloads or claim to perform an atomic update. Those responsibilities belong to the eventual authorised executor.',null,'A useful preflight result says which requests need further execution checks.'),p('Require explicit approval and the expected snapshot','The proposal carries the revision of the target as it was when reviewed. That recorded view is a snapshot; it is not a reservation preventing later edits. Compare expected_revision with the target’s current snapshot revision, and exclude a missing target.\n\nOnly the Boolean value true counts as approval in this example. Text that spells true is a string, which is a different typed value. The distinction keeps an ambiguous response from silently becoming permission to change a record.\n\nA stale request should return to review or be recalculated according to policy. Quietly changing expected_revision to the latest number would remove the protection the field was meant to provide.',null,'Approval and freshness are independent conditions.',[example('Inspect the revision mismatch','This program reports the two revisions rather than applying a change.',"request={'expected_revision':3}\nasset={'revision':4}\nprint(request['expected_revision']==asset['revision'])",'False','The approved request used older state. A new plan may need new approval.')]),p('The commit must enforce the concurrency rule','Between a browser preflight and a server write, another update can occur. Use a database-supported transaction and locking or conditional-update strategy whose isolation semantics have been checked for the deployed database.\n\nA read in one transaction followed by an unconditional write in another is not optimistic concurrency control. Even a predicate and write in one statement need the engine’s documented concurrent-update semantics; do not assume a snapshot comparison creates a lock.',null,'The workshop intentionally stops before commit and cannot establish transaction isolation.'),withRef(p('Parameterise the approved write and verify its result','The external example demonstrates the simpler unit: update one uniquely identified asset inside an application-managed transaction, then verify exactly one target was returned before committing. It does not implement the revision conflict policy by itself.\n\nUse an authorised driver session, a parameterised reviewed query and explicit rollback when the matched target count violates the contract. Do not execute arbitrary Cypher generated by a user or model as the writer role.',null,'Application validation, authorisation and concurrency control remain required around this query.'),ref('A parameterised write inside the executor transaction','This query must be run inside the transaction described in setup, not pasted into an unrestricted production console.',"MATCH (a:Asset {id:$asset})\nSET a.status=$status\nRETURN a.id AS updated",['In a disposable database, create unique Asset.id values and install the uniqueness constraint from the preceding lesson.','Use a Neo4j driver transaction. Bind asset P7 and a validated status. Read the returned rows, require exactly one, and roll back on mismatch before commit.','For revision-sensitive requests, add a tested locking/conditional-update protocol at that same transaction boundary. This snippet does not supply that protocol.'],'The query changes one validated field. The transaction determines whether that change commits.','https://neo4j.com/docs/python-manual/current/transactions/')),p('Retries must not repeat outside effects','A driver-managed transaction function may be invoked again after a transient failure. Sending an email, charging a service or issuing a physical maintenance action inside that retried function can repeat the effect even if the database transaction rolled back.\n\nKeep external actions out of automatically retried database callbacks. Where an action must follow a commit, use a durable outbox or another explicit delivery design with idempotency keys and reconciliation. A database rollback cannot undo an email already sent.',null,'Exactly-once business effects require more than calling MERGE or retrying a transaction.'),p('MERGE and DELETE need their own identity and scope rules','MERGE matches or creates the supplied pattern. Match stable identity separately from mutable fields and back required uniqueness with constraints. A replayed logical request should have a stable idempotency identity if its outcome must be reconciled.\n\nDELETE of a node with relationships and DETACH DELETE have different consequences. Broad deletion patterns can remove connected history. Preview the exact target identities and use least-privilege permissions; the lesson’s preflight does not authorise a deletion.',null,'Read the write pattern as a description of everything it may affect.'),p('Test stale, missing and ambiguously typed requests','The challenge checks explicit approval, known target and matching integer revision. It retains each eligible target ID once for this report. Real executors still need per-request identity, payload validation and conflict handling when several proposals target the same node.\n\nThat limited output makes the lesson’s claim testable: the records qualify for further execution checks under this snapshot. It never says those changes have been safely committed.',null,'Keep the displayed result at the same level of authority as the mechanism that produced it.')],checkpoint:[q('A request is approved and expects revision 3. The current snapshot has revision 4.','Should the preflight select it?',['No, it is stale','Yes, approval overrides every future change','Yes, replace its expected revision automatically'],0,'The approval was attached to older state.'),tf('A request passes a browser snapshot check.','That check alone protects a later database write from concurrent updates.',false,'The state can change again before commit.')],quiz:[q('A managed database transaction callback is retried. It also sends an email.','What can happen?',['The email can be sent more than once','The database always rolls back the email','Retries cannot repeat callbacks'],0,'External effects do not share the database rollback boundary.'),tf('The exercise returns eligible target IDs without writing to a database.','It should describe its result as preflight evidence rather than committed changes.',true,'The output must not promise capabilities the mechanism does not provide.')],practice:[({ ...exercise('Select requests that still match the approved snapshot',[
  "An approved request may be stale by the time it reaches the update queue. Select only targets whose current revision still matches the approved request.",
  "Implement eligible_targets(graph,requests). Keep requests with approved is True, an existing target and an integer expected_revision equal to the node’s integer revision. Exclude booleans as revisions. Return distinct sorted target IDs. This is preflight only."
],'eligible_targets','graph, requests',"    nodes={n['id']:n for n in graph['nodes']}\n    selected=set()\n    for r in requests:\n        node=nodes.get(r['id'])\n        if r.get('approved') is True and node is not None and type(r.get('expected_revision')) is int and type(node.get('revision')) is int and r['expected_revision']==node['revision']:\n            selected.add(r['id'])\n    return sorted(selected)",`print(eligible_targets(${py(revisionGraph)}, ${py(requests)}))`,['P7'],[
  "Find the target node, then check approval and the exact expected/current revision match independently.",
  "Use type(revision) is int to exclude booleans. Return distinct sorted target IDs without applying an update."
],[check('Stale target excluded',`eligible_targets(${py(revisionGraph)}, ${py(requests)})`,['P7']),check('Unknown target',`eligible_targets(${py(revisionGraph)}, [{'id':'P9','approved':True,'expected_revision':2}])`,[]),check('String approval is not approval',`eligible_targets(${py(revisionGraph)}, [{'id':'P7','approved':'true','expected_revision':2}])`,[]),check('Correct refreshed request',`eligible_targets(${py(revisionGraph)}, [{'id':'P8','approved':True,'expected_revision':4}])`,['P8'])]), question: "Which approved requests still refer to the revision that was reviewed?" })],build:build('Check approval against the graph snapshot','An approved request can become stale before it reaches the executor.','Keep explicitly approved requests, compare expected revisions with current node revisions, then collect distinct eligible target IDs. This does not commit any update.',{graph:'Current node snapshot',requests:'Proposed requests and approvals'},[sample('P8 changed after the proposal',{graph:revisionGraph,requests},['P7']),sample('Approval arrives as a string',{graph:revisionGraph,requests:[{id:'P7',expected_revision:2,approved:'true'}]},[]),sample('A reviewed P8 request uses the current revision',{graph:revisionGraph,requests:[{id:'P8',expected_revision:4,approved:true}]},['P8'])],identifiers(op('gdRevisions',op('gdApproved',s('requests')),s('graph'))),['Only explicit approval passes the first branch.','A snapshot comparison is preparation, not an atomic database update.']),});

const importBatch=[edge('a','P7','S1'),edge('new','P8','S1'),edge('lost','P7','missing'),edge('a','P7','P8')];
const importBody="    import json\n    known={n['id'] for n in graph['nodes']}\n    seen={e['id']:e for e in graph['edges']}\n    accepted=[]\n    for e in batch:\n        if not all(isinstance(e.get(k),str) and e[k] for k in ['id','source','target','type']): continue\n        if e['id'] in seen: continue\n        if e['source'] not in known or e['target'] not in known: continue\n        seen[e['id']]=e\n        accepted.append(e['id'])\n    return sorted(accepted)";
