function insertPart(record,index,entry){
 const technical=record.parts.find(part=>part.title===record.technicalStart);
 const checkpointParts=record.checkpoints.map(checkpoint=>record.parts.find(part=>part.title===checkpoint.after));
 record.parts.splice(index,0,entry);
 for(const [i,part] of record.parts.entries())part.title=`${i+1}. ${part.title.replace(/^\d+\. /,'')}`;
 record.technicalStart=technical.title;
 record.checkpoints.forEach((checkpoint,i)=>{checkpoint.after=checkpointParts[i].title;checkpoint.title=`Questions on Parts 1 to ${record.parts.indexOf(checkpointParts[i])+1}`;});
}
insertPart(shortest,2,p('Use the heap to revisit a tentative choice','A Python heap stores the candidate with the smallest first tuple value at its front. heappush adds a candidate; heappop removes the cheapest one. The second tuple item is the node ID, which also provides a deterministic tie break for these string IDs.\n\nWe do not need to find and delete an old heap entry when a better route appears. Update best and push the cheaper candidate. When the old entry eventually comes out, compare its cost with best and skip it if they differ. The program below isolates that mechanism before the challenge adds graph traversal.',null,'The heap remembers candidates. The best dictionary records the current best estimate for each node.',[
 example('Replace B’s nine-minute candidate','Suppose A has already produced candidates C at two and B at nine. Expanding C finds a cheaper way to B.',"import heapq\nbest={'B':9,'C':2}\npending=[(2,'C'),(9,'B')]\nheapq.heapify(pending)\ncost,node=heapq.heappop(pending)\nproposed=cost+2  # C to B takes two minutes.\nif proposed < best['B']:\n    best['B']=proposed\n    heapq.heappush(pending,(proposed,'B'))\nwhile pending:\n    cost,node=heapq.heappop(pending)\n    if cost != best[node]:\n        print('skip',node,cost)\n        continue\n    print('use',node,cost)",'use B 4\nskip B 9','The old entry remains in the heap but cannot overwrite the improved estimate. This example teaches one relaxation, not the full shortest-path function.')
]));
shortest.history.sources.unshift(source('Dijkstra, A note on two problems in connexion with graphs, 1959','https://ir.cwi.nl/pub/9256'));
shortest.history.blocks.unshift('Dijkstra’s 1959 paper described a procedure for finding the shortest route between nodes in a weighted graph. The useful step is to separate tentative distances from settled ones: with nonnegative lengths, the least tentative distance cannot later be improved by taking a detour through a more expensive unsettled node.');
imports.parts[2].references[0].setup=[
 'Use a disposable current Neo4j database supporting relationship property uniqueness constraints. Run CREATE CONSTRAINT import_asset_id IF NOT EXISTS FOR (a:Asset) REQUIRE a.id IS UNIQUE. Then run CREATE CONSTRAINT dependency_import_id IF NOT EXISTS FOR ()-[r:DEPENDS_ON]-() REQUIRE r.import_id IS UNIQUE. These uniqueness constraints do not require property presence; the importer validates it.',
 "Create the complete stored fixture: CREATE (p:Asset {id:'P7'}),(q:Asset {id:'P8'}),(s:Asset {id:'S1'}),(p)-[:DEPENDS_ON {import_id:'a'}]->(s).",
 "Bind rows to [{id:'a',source:'P7',target:'S1'},{id:'new',source:'P8',target:'S1'}] through the driver. This particular write schema has only immutable endpoint identities and the fixed DEPENDS_ON type; reject additional fields rather than silently ignoring payload properties.",
 'Run in a transaction after source and endpoint validation. The first row matches the stored relationship and the second creates one. Running the same batch again should match both. A reused import ID on different endpoints must fail the uniqueness constraint and enter conflict handling. Reconcile returned IDs against the staged input so an unmatched endpoint is not silently lost.'
];
